        'left': (-1, 0),
        'right': (1, 0),
        'stay': (0, 0)
    }

    # Helper to check passability
    def is_passable(x, y):
        if 0 <= x < width and 0 <= y < height:
            cell = grid[y][x]
            return cell != 'wall'
        return False

    # Find resource positions
    resources = []
    for y in range(height):
