        elif dx < 0:
            move_options.append(('left', (-1, 0)))
        if dy > 0:
            move_options.append(('down', (0, 1)))
        elif dy < 0:
            move_options.append(('up', (0, -1)))
        for name, (mx, my) in move_options:
            new_x, new_y = ax + mx, ay + my
            if is_passable(new_x, new_y):
                return [mx, my]
        if is_passable(ax, ay):
            return [0, 0]

    # Territory control: explore unvisited or less visited
    # For simplicity, pick random passable directions
